from pathlib import Path
from html import escape
import json,re
R=Path(__file__).resolve().parents[1]
M='#500000'; INK='#211b1b'; CREAM='#f5f2eb'
def p(s): return f'<p style="margin:0 0 16px;font-size:16px;line-height:26px;">{s}</p>'
def label(s): return f'<p style="margin:0 0 14px;font:700 11px/16px Arial,sans-serif;letter-spacing:2px;text-transform:uppercase;">{s}</p>'
def h(s,size=34): return f'<h2 class="headline-{size}" style="margin:0 0 18px;font:700 {size}px/{size+3}px Georgia,serif;letter-spacing:-1px;">{s}</h2>'
def img(n,alt,w=600): return f'<img src="../assets/{n}" width="{w}" alt="{escape(alt)}" style="display:block;border:0;width:100%;max-width:{w}px;height:auto;">'
def link(text,key): return f'<a href="https://example.invalid/{key}" style="color:inherit;text-decoration:underline;font-weight:bold;">{text}</a>'
def button(text,key): return f'<table role="presentation" cellspacing="0" cellpadding="0"><tr><td bgcolor="{M}" style="mso-padding-alt:16px 24px;"><a href="https://example.invalid/{key}" style="display:inline-block;background:{M};border:1px solid #ffffff;color:#ffffff;font:700 14px/20px Arial,sans-serif;text-decoration:none;padding:16px 24px;mso-padding-alt:0;">{text} &nbsp; &rarr;</a></td></tr></table>'
def block(body,bg='#ffffff',color=INK,pad='32px 36px'): return f'<tr><td class="pad surface" bgcolor="{bg}" style="background-color:{bg};color:{color};padding:{pad};font-family:Arial,sans-serif;">{body}</td></tr>'
mods={}; specs=[]
def add(id,name,family,body,fields,limits):
 mods[id]=f'<!-- BEGIN {id}: {name} -->\n{body}\n<!-- END {id} -->'
 specs.append(dict(id=id,name=name,family=family,fields=fields,limits=limits))
