add('AT-01','Away game matchup','Athletics',block(label('SATURDAY, OCTOBER 24 / FOOTBALL')+h('Take it<br>on the road.',44)+'<table role="presentation" width="100%"><tr><td style="font:700 24px/32px Georgia,serif;color:#ffffff;">TEXAS A&amp;M<br><span style="font:14px Arial,sans-serif;">at No. 13 Alabama</span></td><td align="right" style="font:700 34px/38px Arial,sans-serif;color:#ffffff;">2:30<span style="font:16px Arial,sans-serif;"> PM</span><br><span style="font:12px Arial,sans-serif;">ABC · Tuscaloosa, Ala.</span></td></tr></table>',M,'#ffffff'),['date','sport','opponent','ranking','time','timezone','broadcast','venue'],'Display timezone after confirmation. The supplied email omits it; do not infer for send. Home/neutral language may be edited, not geometry.')
