CSS='''body,table,td,a{-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%}table{border-collapse:collapse;mso-table-lspace:0pt;mso-table-rspace:0pt}img{-ms-interpolation-mode:bicubic}a{color:inherit} @media screen and (max-width:620px){.container{width:100%!important}.pad{padding-left:22px!important;padding-right:22px!important}.stack{display:block!important;width:100%!important;padding:0 0 24px!important}h1,h2{overflow-wrap:break-word}.headline-34,.headline-42,.headline-44,.headline-46{font-size:34px!important;line-height:37px!important;letter-spacing:-1px!important}} @media (prefers-color-scheme:dark){body{background:#211b1b!important}}'''
def shell(title,body,pre='Wake up with the Aggies. A weekend worth catching up on.'):
 return f'''<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{escape(title)}</title><style>{CSS}</style><!--[if mso]><style>body,table,td,a{{font-family:Arial,sans-serif!important}}</style><![endif]--></head><body style="margin:0;padding:0;background:#e9e5df;"><div style="display:none;font-size:1px;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;">{pre}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center"><!--[if mso]><table role="presentation" width="600"><tr><td><![endif]--><table role="presentation" class="container" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;">{body}</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>'''
