campaign_essentials=block(label('YOUR MEMBERSHIP')+h('More than a seat.',32)+p('Exclusive access to four private meetings during the season with players and coaches, over a complimentary meal.')+p('Memberships begin as low as $1,000.'),CREAM)
for slug,title,desc,subject,pre,ids in recipes:
 body=''.join(campaign_essentials if slug=='campaign' and i=='CV-02' else (block(button('View membership information','DUGOUT_URL')) if slug=='campaign' and i=='CV-03' else mods[i]) for i in ids)
 if slug!='aggie-am': body=body.replace(' To stop receiving the Aggie AM, '+link('click here','PREFERENCES_URL')+', and uncheck the Aggie AM box.','')
 (R/'templates'/f'{slug}.html').write_text(shell(title,body,pre))
 (R/'templates'/f'{slug}.txt').write_text(f'Subject: {subject}\nPreheader: {pre}\n\nREVIEW SAMPLE. Content from the supplied October 19, 2026 edition.\n'+re.sub('<[^>]+>',' ',body).replace('&nbsp;',' ')+'\n\nReplace every example.invalid link with an approved destination before sending.\n')
for id,body in mods.items():
 (R/'modules'/f'{id}.html').write_text(body)
 (R/'modules'/f'{id}-preview.html').write_text(shell(id,body))
(R/'source'/'manifest.json').write_text(json.dumps({'tokens':{'maroon':M,'ink':INK,'cream':CREAM,'emailWidth':600,'gutter':36,'mobileGutter':22,'bodyFont':'Arial','displayFont':'Georgia'},'components':specs,'templates':[dict(slug=s,name=t,description=d,subject=sub,preheader=pre,modules=ids) for s,t,d,sub,pre,ids in recipes]},indent=2))
print('Built',len(mods),'modules and',len(recipes),'templates')
# Keep catalog metadata and field contracts synchronized with module output.
(R/'manifest.js').write_text('window.LIBRARY = '+(R/'source/manifest.json').read_text()+';')
contracts=['# Component contracts','', 'All fragments are complete table rows. Insert into the shared 600px shell; the head resets/media query and Outlook wrapper are required. These files are source components, not tested native Eloqua elements.','', '| ID | Component | Family | Editable fields | Limits and rules |','|---|---|---|---|---|']
for c in specs: contracts.append('| '+' | '.join([c['id'],c['name'],c['family'],', '.join(c['fields']) or 'None',c['limits']])+' |')
contracts+=['','## Variants and dependencies','','Only variants actually shown in the catalog are built. Home/neutral matchups, loss treatments, alternative story crops and extra card counts require a controlled source edit and revalidation. No unbuilt variant is implied by the component name.','','ID-03, UT-04 and a masthead are required in each composition. UT-01 and UT-02 are source Aggie AM sponsorship placements. ED-03 requires the stack class and shared media query. Images use ../assets relative to template/module directories until Eloqua remaps them.','','Campaign uses documented CV-02 and CV-03 overrides in build.py: membership benefits and membership CTA. Footer behavior varies by recipe: only Aggie AM includes the Aggie AM-specific opt-out sentence.','', 'Staff may edit text, alt text, approved URLs and approved images. Staff must preserve width, table nesting, classes, explicit backgrounds, spacing and conditional comments. These are workflow rules, not editor-enforced locks.']
(R/'docs/COMPONENTS.md').write_text('\n'.join(contracts)+'\n')
# Plain-text companions retain link destinations and semantic reading order.
from html.parser import HTMLParser
from html import unescape
class TextEmail(HTMLParser):
 def __init__(self):super().__init__();self.out=[];self.url=''
 def handle_starttag(self,t,a):
  d=dict(a)
  if t in ['p','h2','tr','table']:self.out.append('\n')
  if t=='br':self.out.append('\n')
  if t=='a':self.url=d.get('href','')
  if t=='img' and d.get('alt'):self.out.append('['+d['alt']+']\n')
 def handle_endtag(self,t):
  if t=='a':self.out.append(' ('+self.url+') ');self.url=''
  if t in ['p','h2','tr','table']:self.out.append('\n')
  if t=='td':self.out.append(' | ')
 def handle_data(self,s):self.out.append(s)
for slug,title,desc,subject,pre,ids in recipes:
 raw=(R/'templates'/f'{slug}.html').read_text(); raw=re.sub(r'<head>.*?</head>','',raw,flags=re.S)
 parser=TextEmail();parser.feed(raw)
 text=re.sub(r'\n[ \t|]+','\n',''.join(parser.out));text=re.sub(r'\n{3,}','\n\n',text)
 (R/'templates'/f'{slug}.txt').write_text(f'Subject: {subject}\nPreheader: {pre}\n\nREVIEW SAMPLE — NOT READY TO SEND\n'+text.strip()+'\n')
